  1	/**
  2	 * Движок раундов — общий для HTTP-ядра и testkit.
  3	 *
  4	 * Операции движка написаны как генераторы: каждое обращение к кошельку — это `yield` операции
  5	 * (`WalletOp`), в ответ генератор получает баланс после неё. Ошибку кошелька драйвер бросает
  6	 * внутрь генератора. Testkit выполняет генератор синхронно с кошельком в памяти (`runSync`),
  7	 * ядро — асинхронно с HTTP-кошельком (`runAsync`). Логика раунда при этом одна.
  8	 */
  9	import type { GameModule, Rng } from '../sdk/types.ts';
 10	import { PlatformError, messageOf } from '../shared/errors.ts';
 11	import { LIMITS, round2 } from '../shared/money.ts';
 12	
 13	/** Операция с кошельком, которую запрашивает движок. Результат — баланс после операции. */
 14	export type WalletOp =
 15	  | { kind: 'balance' }
 16	  | { kind: 'bet' | 'payout'; txId: string; roundId: string; amount: number };
 17	
 18	/** Генератор операции движка: отдаёт `WalletOp`, получает баланс, возвращает `T`. */
 19	export type EngineGen<T> = Generator<WalletOp, T, number>;
 20	
 21	/** Раунд в хранилище. Параметры и состояние игры хранятся в виде JSON. */
 22	export interface RoundRecord {
 23	  roundId: string;
 24	  gameId: string;
 25	  bet: number;
 26	  params: unknown;
 27	  state: unknown;
 28	  status: 'open' | 'closed';
 29	  /** Выплата закрытого раунда, `null` пока раунд открыт. */
 30	  payout: number | null;
 31	  /** Игра завершила раунд, но выплата ещё не подтверждена кошельком. */
 32	  pendingPayout: number | null;
 33	  /** Раунд аннулирован из-за ошибки игры в `start`: ставка возвращена, `view` = `null`. */
 34	  voided: boolean;
 35	}
 36	
 37	/** Ответ раунда — одинаковый у HTTP API и testkit. */
 38	export interface RoundView {
 39	  roundId: string;
 40	  gameId: string;
 41	  bet: number;
 42	  status: 'open' | 'closed';
 43	  view: unknown;
 44	  payout: number | null;
 45	  balance: number;
 46	}
 47	
 48	/** Ответ открытия игры. */
 49	export interface OpenResult {
 50	  gameId: string;
 51	  limits: { min: number; max: number };
 52	  balance: number;
 53	  activeRound: RoundView | null;
 54	}
 55	
 56	/** Хранилище раундов. Методы синхронные; `get`/`findOpen` возвращают независимую копию. */
 57	export interface RoundStore {
 58	  get(roundId: string): RoundRecord | undefined;
 59	  findOpen(gameId: string): RoundRecord | undefined;
 60	  save(round: RoundRecord): void;
 61	}
 62	
 63	/** Настройки движка. */
 64	export interface EngineOptions {
 65	  games: GameModule[];
 66	  store: RoundStore;
 67	  rng: Rng;
 68	  newRoundId: () => string;
 69	}
 70	
 71	/** Движок раундов: лимиты, порядок проверок, вызовы игры, списание и выплата. */
 72	export class RoundEngine {
 73	  /** Подключённые игры по `id`. */
 74	  readonly games: ReadonlyMap<string, GameModule>;
 75	  readonly #store: RoundStore;
 76	  readonly #rng: Rng;
 77	  readonly #newRoundId: () => string;
 78	
 79	  /** @param opts игры, хранилище раундов, rng и генератор идентификаторов раундов */
 80	  constructor(opts: EngineOptions) {
 81	    const games = new Map<string, GameModule>();
 82	    for (const g of opts.games) {
 83	      if (!g || typeof g.id !== 'string') throw new TypeError('game module must have a string id');
 84	      if (games.has(g.id)) throw new TypeError(`duplicate game id: ${g.id}`);
 85	      games.set(g.id, g);
 86	    }
 87	    this.games = games;
 88	    this.#store = opts.store;
 89	    this.#rng = opts.rng;
 90	    this.#newRoundId = opts.newRoundId;
 91	  }
 92	
 93	  /** Открытие игры: лимиты, баланс и незавершённый раунд. Досылает выплату, если она не прошла раньше. */
 94	  *open(gameId: string): EngineGen<OpenResult> {
 95	    this.#game(gameId);
 96	    let round = this.#store.findOpen(gameId);
 97	    if (round && round.pendingPayout !== null) {
 98	      yield* this.#settle(round, round.pendingPayout);
 99	      round = undefined;
100	    }
101	    const balance: number = yield { kind: 'balance' };
102	    return { gameId, limits: { min: LIMITS.min, max: LIMITS.max }, balance, activeRound: round ? this.#view(round, balance) : null };
103	  }
104	
105	  /**
106	   * Новый раунд. Порядок проверок: игра → лимиты → параметры → открытый раунд → списание → `start`.
107	   * Кошелёк не вызывается, пока не пройдены все проверки без денег.
108	   */
109	  *startRound(gameId: string, bet: unknown, params: unknown): EngineGen<RoundView> {
110	    const game = this.#game(gameId);
111	    const amount = checkBet(bet);
112	    const p = toJson(callGame(() => game.validateParams(params), 'INVALID_PARAMS'));
113	    if (this.#store.findOpen(gameId)) throw new PlatformError('ROUND_ALREADY_OPEN');
114	
115	    const roundId = this.#newRoundId();
116	    const round: RoundRecord = {
117	      roundId,
118	      gameId,
119	      bet: amount,
120	      params: p,
121	      state: null,
122	      status: 'open',
123	      payout: null,
124	      pendingPayout: null,
125	      voided: false,
126	    };
127	    const afterBet: number = yield { kind: 'bet', txId: `${roundId}:bet`, roundId, amount };
128	
129	    let step: unknown;
130	    try {
131	      step = game.start({ bet: amount, params: toJson(p), rng: this.#rng });
132	    } catch (e) {
133	      // У раунда нет состояния, продолжать его нельзя: аннулируем и возвращаем ставку.
134	      round.voided = true;
135	      yield* this.#settle(round, amount);
136	      throw new PlatformError('INTERNAL_ERROR', `Игра не смогла начать раунд: ${messageOf(e)}`);
137	    }
138	    return yield* this.#apply(game, round, step, afterBet, true);
139	  }
140	
141	  /** Ход в открытом раунде. При `INVALID_ACTION` состояние раунда и баланс не меняются. */
142	  *action(roundId: string, action: unknown): EngineGen<RoundView> {
143	    const round = this.#store.get(roundId);
144	    if (!round) throw new PlatformError('ROUND_NOT_FOUND');
145	    if (round.status === 'closed') throw new PlatformError('ROUND_CLOSED');
146	    const game = this.games.get(round.gameId);
147	    if (!game) throw new PlatformError('INTERNAL_ERROR', `Игра ${round.gameId} не подключена`);
148	    if (round.pendingPayout !== null) {
149	      // Игра уже завершила раунд, ждём только выплату — досылаем её, ходить больше нельзя.
150	      yield* this.#settle(round, round.pendingPayout);
151	      throw new PlatformError('ROUND_CLOSED');
152	    }
153	    const step = callGame(
154	      () => game.action({ bet: round.bet, params: round.params, state: round.state, action, rng: this.#rng }),
155	      'INVALID_ACTION',
156	    );
157	    return yield* this.#apply(game, round, step, null, false);
158	  }
159	
160	  /** Применяет шаг игры к раунду: сохраняет состояние, а на `finished` — выплачивает и закрывает. */
161	  *#apply(game: GameModule, round: RoundRecord, step: unknown, knownBalance: number | null, isStart: boolean): EngineGen<RoundView> {
162	    if (!isValidStep(step)) {
163	      if (isStart) {
164	        // Ставка уже списана: раунд остаётся открытым с тем, что вернула игра.
165	        round.state = safeJson((step as { state?: unknown } | null)?.state);
166	        this.#store.save(round);
167	      }
168	      throw new PlatformError('INTERNAL_ERROR', `Игра ${game.id} вернула некорректный шаг`);
169	    }
170	    const state = toJson(step.state);
171	    if (step.status === 'continue') {
172	      round.state = state;
173	      this.#store.save(round);
174	      const balance: number = knownBalance ?? (yield { kind: 'balance' });
175	      return this.#view(round, balance);
176	    }
177	    round.state = state;
178	    const balance = yield* this.#settle(round, round2(step.payout));
179	    return this.#view(round, balance);
180	  }
181	
182	  /** Выплата `<roundId>:payout` и закрытие раунда. До ответа кошелька раунд сохранён как «ждёт выплаты». */
183	  *#settle(round: RoundRecord, amount: number): EngineGen<number> {
184	    round.pendingPayout = amount;
185	    this.#store.save(round);
186	    const balance: number = yield { kind: 'payout', txId: `${round.roundId}:payout`, roundId: round.roundId, amount };
187	    round.status = 'closed';
188	    round.payout = amount;
189	    round.pendingPayout = null;
190	    this.#store.save(round);
191	    return balance;
192	  }
193	
194	  #view(round: RoundRecord, balance: number): RoundView {
195	    let view: unknown = null;
196	    if (!round.voided) {
197	      const game = this.games.get(round.gameId);
198	      if (!game) throw new PlatformError('INTERNAL_ERROR', `Игра ${round.gameId} не подключена`);
199	      try {
200	        view = toJson(game.publicView(round.state, round.status === 'closed'));
201	      } catch (e) {
202	        throw new PlatformError('INTERNAL_ERROR', `Игра ${game.id} не смогла показать раунд: ${messageOf(e)}`);
203	      }
204	    }
205	    return { roundId: round.roundId, gameId: round.gameId, bet: round.bet, status: round.status, view, payout: round.payout, balance };
206	  }
207	
208	  #game(gameId: unknown): GameModule {
209	    const game = typeof gameId === 'string' ? this.games.get(gameId) : undefined;
210	    if (!game) throw new PlatformError('GAME_NOT_FOUND');
211	    return game;
212	  }
213	}
214	
215	/** Ставка: конечное число, округлённое до центов и попадающее в лимиты. Иначе `BET_OUT_OF_LIMITS`. */
216	function checkBet(bet: unknown): number {
217	  if (typeof bet !== 'number' || !Number.isFinite(bet)) throw new PlatformError('BET_OUT_OF_LIMITS');
218	  const amount = round2(bet);
219	  if (amount < LIMITS.min || amount > LIMITS.max) throw new PlatformError('BET_OUT_OF_LIMITS');
220	  return amount;
221	}
222	
223	/** Вызов игры: ожидаемый код (`INVALID_PARAMS`/`INVALID_ACTION`) пробрасывается, остальное — `INTERNAL_ERROR`. */
224	function callGame<T>(fn: () => T, expected: 'INVALID_PARAMS' | 'INVALID_ACTION'): T {
225	  try {
226	    return fn();
227	  } catch (e) {
228	    const code = (e as { code?: unknown } | null)?.code;
229	    if (code === expected) {
230	      const msg = e instanceof Error && e.message && e.message !== expected ? e.message : undefined;
231	      throw new PlatformError(expected, msg);
232	    }
233	    throw new PlatformError('INTERNAL_ERROR', `Ошибка игры: ${messageOf(e)}`);
234	  }
235	}
236	
237	function isValidStep(step: unknown): step is { status: 'continue'; state: unknown } | { status: 'finished'; state: unknown; payout: number } {
238	  if (!step || typeof step !== 'object') return false;
239	  const s = step as { status?: unknown; payout?: unknown };
240	  if (s.status === 'continue') return true;
241	  return s.status === 'finished' && typeof s.payout === 'number' && Number.isFinite(s.payout) && s.payout >= 0;
242	}
243	
244	/** Копия значения через JSON — так же, как оно переживёт хранение на диске. */
245	function toJson<T>(value: T): T {
246	  if (value === undefined) return value;
247	  try {
248	    return JSON.parse(JSON.stringify(value)) as T;
249	  } catch (e) {
250	    throw new PlatformError('INTERNAL_ERROR', `Состояние игры не сериализуется в JSON: ${messageOf(e)}`);
251	  }
252	}
253	
254	function safeJson(value: unknown): unknown {
255	  try {
256	    return toJson(value);
257	  } catch {
258	    return null;
259	  }
260	}
261	
262	/** Выполняет операцию движка синхронно. `exec` выполняет операцию кошелька или бросает ошибку. */
263	export function runSync<T>(gen: EngineGen<T>, exec: (op: WalletOp) => number): T {
264	  let r = gen.next();
265	  while (!r.done) {
266	    let balance: number;
267	    try {
268	      balance = exec(r.value);
269	    } catch (e) {
270	      r = gen.throw(e);
271	      continue;
272	    }
273	    r = gen.next(balance);
274	  }
275	  return r.value;
276	}
277	
278	/** Выполняет операцию движка асинхронно (кошелёк по HTTP). */
279	export async function runAsync<T>(gen: EngineGen<T>, exec: (op: WalletOp) => Promise<number>): Promise<T> {
280	  let r = gen.next();
281	  while (!r.done) {
282	    let balance: number;
283	    try {
284	      balance = await exec(r.value);
285	    } catch (e) {
286	      r = gen.throw(e);
287	      continue;
288	    }
289	    r = gen.next(balance);
290	  }
291	  return r.value;
292	}
  1	/** Хранилища раундов: в памяти (testkit) и на диске (`data/rounds.json`, ядро). */
  2	import fs from 'node:fs';
  3	import path from 'node:path';
  4	import type { RoundRecord, RoundStore } from './engine.ts';
  5	
  6	/** Раунды в памяти. Записи хранятся как JSON, поэтому чтение всегда даёт независимую копию. */
  7	export class MemoryRoundStore implements RoundStore {
  8	  /** Раунды по `roundId` в виде JSON-строк. */
  9	  protected readonly rounds = new Map<string, string>();
 10	  readonly #openByGame = new Map<string, string>();
 11	
 12	  /** Раунд по идентификатору. */
 13	  get(roundId: string): RoundRecord | undefined {
 14	    const s = this.rounds.get(roundId);
 15	    return s === undefined ? undefined : (JSON.parse(s) as RoundRecord);
 16	  }
 17	
 18	  /** Открытый раунд игры, если есть. */
 19	  findOpen(gameId: string): RoundRecord | undefined {
 20	    const id = this.#openByGame.get(gameId);
 21	    return id === undefined ? undefined : this.get(id);
 22	  }
 23	
 24	  /** Сохраняет раунд целиком. */
 25	  save(round: RoundRecord): void {
 26	    this.rounds.set(round.roundId, JSON.stringify(round));
 27	    if (round.status === 'open') this.#openByGame.set(round.gameId, round.roundId);
 28	    else if (this.#openByGame.get(round.gameId) === round.roundId) this.#openByGame.delete(round.gameId);
 29	  }
 30	}
 31	
 32	/** Раунды на диске: файл перечитывается при создании и перезаписывается после каждого изменения. */
 33	export class FileRoundStore extends MemoryRoundStore {
 34	  readonly #file: string;
 35	
 36	  /** @param file путь к `rounds.json`; каталог создаётся при необходимости */
 37	  constructor(file: string) {
 38	    super();
 39	    this.#file = file;
 40	    if (fs.existsSync(file)) {
 41	      const data = JSON.parse(fs.readFileSync(file, 'utf8')) as { rounds?: Record<string, RoundRecord> };
 42	      for (const r of Object.values(data.rounds ?? {})) super.save(r);
 43	    }
 44	  }
 45	
 46	  /** Сохраняет раунд и записывает файл (через временный файл и rename). */
 47	  override save(round: RoundRecord): void {
 48	    super.save(round);
 49	    const body = [...this.rounds].map(([id, json]) => `${JSON.stringify(id)}:${json}`).join(',\n');
 50	    fs.mkdirSync(path.dirname(this.#file), { recursive: true });
 51	    const tmp = `${this.#file}.tmp`;
 52	    fs.writeFileSync(tmp, `{"rounds":{\n${body}\n}}\n`);
 53	    fs.renameSync(tmp, this.#file);
 54	  }
 55	}
  1	/**
  2	 * Кошелёк партнёра — отдельный HTTP-сервис, который владеет балансом игрока `player-1`.
  3	 *
  4	 * - `GET /balance` → `{ balance }`
  5	 * - `POST /bet { txId, roundId, amount }` → `{ balance }` или `402 INSUFFICIENT_FUNDS`
  6	 * - `POST /payout { txId, roundId, amount }` → `{ balance }`
  7	 *
  8	 * Повтор `txId` с теми же данными возвращает сохранённый ответ, с другими — `409 TX_CONFLICT`.
  9	 * Баланс и журнал хранятся в `<dataDir>/wallet.json`.
 10	 */
 11	import fs from 'node:fs';
 12	import http from 'node:http';
 13	import path from 'node:path';
 14	import { PlatformError } from '../shared/errors.ts';
 15	import { listen, readJson, sendError, sendJson, type RunningServer } from '../shared/http.ts';
 16	import { round2 } from '../shared/money.ts';
 17	
 18	export type { RunningServer };
 19	
 20	/** Начальный баланс игрока. */
 21	export const START_BALANCE = 100;
 22	/** Единственный игрок. */
 23	export const PLAYER_ID = 'player-1';
 24	
 25	/** Запись журнала транзакций кошелька. */
 26	export interface WalletTx {
 27	  type: 'bet' | 'payout';
 28	  roundId: string;
 29	  amount: number;
 30	  /** Сохранённый ответ: повтор `txId` отдаёт его без изменений. */
 31	  status: number;
 32	  body: unknown;
 33	}
 34	
 35	/** Содержимое `wallet.json`. */
 36	export interface WalletState {
 37	  player: string;
 38	  balance: number;
 39	  transactions: Record<string, WalletTx>;
 40	}
 41	
 42	/** Настройки запуска кошелька. */
 43	export interface WalletOptions {
 44	  /** Порт; 0 — свободный. */
 45	  port: number;
 46	  /** Каталог данных, где лежит `wallet.json`. */
 47	  dataDir: string;
 48	  /** Адрес прослушивания; по умолчанию `127.0.0.1`. */
 49	  host?: string;
 50	}
 51	
 52	/** Запускает HTTP-сервис кошелька. */
 53	export async function startWallet(opts: WalletOptions): Promise<RunningServer> {
 54	  const file = path.join(opts.dataDir, 'wallet.json');
 55	  const state = loadState(file);
 56	
 57	  const persist = (): void => {
 58	    fs.mkdirSync(opts.dataDir, { recursive: true });
 59	    const tmp = `${file}.tmp`;
 60	    fs.writeFileSync(tmp, `${JSON.stringify(state, null, 1)}\n`);
 61	    fs.renameSync(tmp, file);
 62	  };
 63	
 64	  const transact = (type: 'bet' | 'payout', input: unknown): { status: number; body: unknown } => {
 65	    const { txId, roundId, amount } = (input ?? {}) as { txId?: unknown; roundId?: unknown; amount?: unknown };
 66	    if (typeof txId !== 'string' || !txId || typeof roundId !== 'string' || !roundId) {
 67	      throw new PlatformError('INVALID_REQUEST', 'Нужны строковые txId и roundId');
 68	    }
 69	    const value = typeof amount === 'number' && Number.isFinite(amount) ? round2(amount) : Number.NaN;
 70	    if (!Number.isFinite(value) || (type === 'bet' ? value <= 0 : value < 0)) {
 71	      return { status: 400, body: { error: { code: 'INVALID_AMOUNT', message: 'Некорректная сумма' } } };
 72	    }
 73	
 74	    const prev = state.transactions[txId];
 75	    if (prev) {
 76	      if (prev.type === type && prev.roundId === roundId && prev.amount === value) return { status: prev.status, body: prev.body };
 77	      return { status: 409, body: { error: { code: 'TX_CONFLICT', message: 'txId уже использован с другими данными' } } };
 78	    }
 79	
 80	    let result: { status: number; body: unknown };
 81	    if (type === 'bet' && value > state.balance) {
 82	      result = { status: 402, body: { error: { code: 'INSUFFICIENT_FUNDS', message: 'Недостаточно средств' }, balance: state.balance } };
 83	    } else {
 84	      state.balance = round2(type === 'bet' ? state.balance - value : state.balance + value);
 85	      result = { status: 200, body: { balance: state.balance } };
 86	    }
 87	    state.transactions[txId] = { type, roundId, amount: value, status: result.status, body: result.body };
 88	    persist();
 89	    return result;
 90	  };
 91	
 92	  const server = http.createServer(async (req, res) => {
 93	    try {
 94	      const url = new URL(req.url ?? '/', 'http://wallet');
 95	      if (req.method === 'GET' && url.pathname === '/balance') return sendJson(res, 200, { balance: state.balance });
 96	      if (req.method === 'POST' && (url.pathname === '/bet' || url.pathname === '/payout')) {
 97	        const body = await readJson(req);
 98	        const r = transact(url.pathname === '/bet' ? 'bet' : 'payout', body);
 99	        return sendJson(res, r.status, r.body);
100	      }
101	      throw new PlatformError('NOT_FOUND');
102	    } catch (e) {
103	      sendError(res, e);
104	    }
105	  });
106	
107	  return listen(server, opts.port, opts.host ?? '127.0.0.1');
108	}
109	
110	function loadState(file: string): WalletState {
111	  if (!fs.existsSync(file)) return { player: PLAYER_ID, balance: START_BALANCE, transactions: {} };
112	  // Битый файл — ошибка запуска: молча сбросить баланс игрока нельзя.
113	  const data = JSON.parse(fs.readFileSync(file, 'utf8')) as Partial<WalletState>;
114	  if (typeof data.balance !== 'number' || !Number.isFinite(data.balance)) throw new Error(`${file}: некорректный баланс`);
115	  return { player: PLAYER_ID, balance: data.balance, transactions: data.transactions ?? {} };
116	}

