402	    15	/** Читает JSON-тело запроса. Пустое тело — `undefined`, битый JSON — `PlatformError('INVALID_REQUEST')`. */
403	    16	export async function readJson(req: http.IncomingMessage): Promise<unknown> {
404	    17	  const chunks: Buffer[] = [];
405	    18	  let size = 0;
406	    19	  for await (const chunk of req) {
407	    20	    size += (chunk as Buffer).length;
408	    21	    if (size > MAX_BODY) throw new PlatformError('INVALID_REQUEST', 'Слишком большое тело запроса');
409	    22	    chunks.push(chunk as Buffer);
410	    23	  }
