412	    25	  if (!text) return undefined;
413	    26	  try {
414	    27	    return JSON.parse(text);
415	    28	  } catch {
416	    29	    throw new PlatformError('INVALID_REQUEST', 'Тело запроса — не JSON');
417	    30	  }
