435	    48	export function listen(server: http.Server, port: number, host: string): Promise<RunningServer> {
436	    49	  return new Promise((resolve, reject) => {
437	    50	    server.once('error', reject);
438	    51	    server.listen(port, host, () => {
439	    52	      server.off('error', reject);
440	    53	      const addr = server.address();
441	    54	      const actual = typeof addr === 'object' && addr ? addr.port : port;
442	    55	      const urlHost = host.includes(':') ? `[${host}]` : host;
443	    56	      resolve({
444	    57	        url: `http://${urlHost}:${actual}`,
445	    58	        close: () =>
446	    59	          new Promise<void>((done) => {
447	    60	            server.close(() => done());
448	    61	            server.closeAllConnections();
449	    62	          }),
450	    63	      });
451	    64	    });
452	    65	  });
453	    66	}
454	// Клиентский SDK платформы. Раздаётся ядром как /sdk.js и даёт интерфейсу игры window.PlatformSDK.
455	//
456	//   PlatformSDK.open()                 → POST /api/games/<id>/open   (id игры — из адреса /games/<id>/…)
457	//   PlatformSDK.startRound(bet, params)→ POST /api/games/<id>/rounds
458	//   PlatformSDK.action(action)         → POST /api/rounds/<roundId>/actions
459	//
460	// Методы возвращают Promise с телом ответа API. Ошибка — отказ объектом { code, message }.
461	// SDK запоминает roundId из open() (activeRound) и из startRound(); без раунда action()
462	// отклоняется с { code: "ROUND_NOT_FOUND" } без запроса к серверу.
463	(function () {
464	  'use strict';
465	
466	  var match = /^\/games\/([^/]+)/.exec(window.location.pathname);
467	  var gameId = match ? decodeURIComponent(match[1]) : null;
468	  var roundId = null;
469	
470	  function fail(code, message) {
471	    return Promise.reject({ code: code, message: message || code });
472	  }
473	
474	  function post(path, body) {
475	    return fetch(path, {
476	      method: 'POST',
477	      headers: { 'content-type': 'application/json' },
478	      body: JSON.stringify(body === undefined ? {} : body),
479	    }).then(
480	      function (res) {
481	        return res.text().then(function (text) {
482	          var data = null;
483	          try {
484	            data = text ? JSON.parse(text) : null;
485	          } catch (e) {
486	            data = null;
487	          }
488	          if (res.ok) return data;
489	          var err = data && data.error;
490	          return fail((err && err.code) || 'HTTP_' + res.status, (err && err.message) || res.statusText);
491	        });
492	      },
493	      function (e) {
494	        return fail('NETWORK_ERROR', e && e.message ? e.message : 'Нет связи с сервером');
495	      },
496	    );
497	  }
498	
499	  function remember(round) {
500	    roundId = round && round.roundId ? round.roundId : null;
501	    return round;
502	  }
503	
504	  window.PlatformSDK = {
505	    /** Идентификатор игры из адреса страницы. */
506	    gameId: gameId,
507	
508	    /** Открывает игру: { gameId, limits, balance, activeRound }. */
509	    open: function () {
510	      if (!gameId) return fail('GAME_NOT_FOUND', 'Страница не относится к игре');
511	      return post('/api/games/' + encodeURIComponent(gameId) + '/open').then(function (res) {
512	        remember(res && res.activeRound);
513	        return res;
514	      });
515	    },
516	
