520	      return post('/api/games/' + encodeURIComponent(gameId) + '/rounds', { bet: bet, params: params }).then(remember);
521	    },
522	
523	    /** Ход в текущем раунде → RoundView. */
524	    action: function (action) {
525	      if (!roundId) return fail('ROUND_NOT_FOUND', 'Нет открытого раунда');
