     2	import http from 'node:http';
     3	import { PlatformError, messageOf } from '../shared/errors.ts';
     4	import type { WalletOp } from './engine.ts';
     5	
     6	const TIMEOUT_MS = 5000;
     7	
     8	/**
     9	 * Создаёт исполнитель операций кошелька по адресу `walletUrl`.
    10	 * `402` → `INSUFFICIENT_FUNDS`; сеть, таймаут, `5xx` → `WALLET_UNAVAILABLE`; прочие отказы → `INTERNAL_ERROR`.
    11	 */
    12	export function walletExecutor(walletUrl: string): (op: WalletOp) => Promise<number> {
    13	  return async (op) => {
    14	    const res =
    15	      op.kind === 'balance'
    16	        ? await call(walletUrl, 'GET', '/balance')
    17	        : await call(walletUrl, 'POST', `/${op.kind}`, { txId: op.txId, roundId: op.roundId, amount: op.amount });
    18	    const body = res.body as { balance?: unknown; error?: { code?: unknown } } | undefined;
    19	    if (res.status === 200 && typeof body?.balance === 'number') return body.balance;
    20	    if (res.status === 402) throw new PlatformError('INSUFFICIENT_FUNDS');
    21	    if (res.status >= 500 || res.status === 200) throw new PlatformError('WALLET_UNAVAILABLE');
    22	    throw new PlatformError('INTERNAL_ERROR', `Кошелёк отклонил операцию: ${String(body?.error?.code ?? res.status)}`);
    23	  };
    24	}
