    26	function call(base: string, method: string, urlPath: string, body?: unknown): Promise<{ status: number; body: unknown }> {
    27	  const payload = body === undefined ? undefined : JSON.stringify(body);
    28	  return new Promise((resolve, reject) => {
    29	    const fail = (e: unknown): void => reject(new PlatformError('WALLET_UNAVAILABLE', `Кошелёк недоступен: ${messageOf(e)}`));
    30	    const req = http.request(
    31	      new URL(urlPath, base),
    32	      {
    33	        method,
    34	        timeout: TIMEOUT_MS,
    35	        headers: payload === undefined ? {} : { 'content-type': 'application/json', 'content-length': Buffer.byteLength(payload) },
    36	      },
    37	      (res) => {
    38	        const chunks: Buffer[] = [];
    39	        res.on('data', (c: Buffer) => chunks.push(c));
    40	        res.on('error', fail);
    41	        res.on('end', () => {
    42	          let parsed: unknown;
    43	          try {
    44	            parsed = JSON.parse(Buffer.concat(chunks).toString('utf8'));
    45	          } catch {
    46	            parsed = undefined;
    47	          }
    48	          resolve({ status: res.statusCode ?? 0, body: parsed });
    49	        });
    50	      },
    51	    );
    52	    req.on('timeout', () => req.destroy(new Error('timeout')));
    53	    req.on('error', fail);
    54	    if (payload !== undefined) req.write(payload);
    55	    req.end();
    56	  });
    57	}
