    49	  let balance = round2(opts.startBalance ?? 100);
    50	  const txs: Tx[] = [];
    51	  let seq = 0;
    52	  const engine = new RoundEngine({
    53	    games: opts.games,
    54	    store: new MemoryRoundStore(),
    55	    rng: opts.rng ?? seededRng(1),
    56	    newRoundId: () => `round-${++seq}`,
    57	  });
    58	
    59	  const exec = (op: WalletOp): number => {
    60	    if (op.kind === 'balance') return balance;
    61	    if (op.kind === 'bet') {
    62	      if (op.amount > balance) throw new PlatformError('INSUFFICIENT_FUNDS');
    63	      balance = round2(balance - op.amount);
    64	    } else {
    65	      balance = round2(balance + op.amount);
    66	    }
    67	    txs.push({ txId: op.txId, type: op.kind, roundId: op.roundId, amount: op.amount, balanceAfter: balance });
