    97	/** Воспроизводимый генератор (mulberry32): одинаковый `seed` — одинаковая последовательность в [0, 1). */
    98	export function seededRng(seed: number): Rng {
    99	  let a = Math.trunc(seed) >>> 0;
   100	  return {
   101	    next(): number {
   102	      a = (a + 0x6d2b79f5) >>> 0;
   103	      let t = a;
   104	      t = Math.imul(t ^ (t >>> 15), t | 1);
   105	      t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
   106	      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
   107	    },
   108	  };
   109	}
