    11	export function round2(x: number): number {
    12	  if (!Number.isFinite(x)) return x;
    13	  const abs = Math.abs(x);
    14	  const s = String(abs);
    15	  const r = s.includes('e') ? Math.round(abs * 100) / 100 : Number(`${Math.round(Number(`${s}e2`))}e-2`);
    16	  if (r === 0) return 0;
    17	  return x < 0 ? -r : r;
    18	}
