    15	/** Читает JSON-тело запроса. Пустое тело — `undefined`, битый JSON — `PlatformError('INVALID_REQUEST')`. */
    16	export async function readJson(req: http.IncomingMessage): Promise<unknown> {
    17	  const chunks: Buffer[] = [];
    18	  let size = 0;
    19	  for await (const chunk of req) {
    20	    size += (chunk as Buffer).length;
    21	    if (size > MAX_BODY) throw new PlatformError('INVALID_REQUEST', 'Слишком большое тело запроса');
    22	    chunks.push(chunk as Buffer);
    23	  }
    24	  const text = Buffer.concat(chunks).toString('utf8').trim();
    25	  if (!text) return undefined;
    26	  try {
    27	    return JSON.parse(text);
    28	  } catch {
    29	    throw new PlatformError('INVALID_REQUEST', 'Тело запроса — не JSON');
    30	  }
    31	}
