    33	/** Отправляет JSON-ответ. */
    34	export function sendJson(res: http.ServerResponse, status: number, body: unknown): void {
    35	  const text = JSON.stringify(body);
    36	  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', 'content-length': Buffer.byteLength(text), 'cache-control': 'no-store' });
    37	  res.end(text);
    38	}
