    40	/** Отправляет ошибку в формате `{ error: { code, message } }`; неизвестная ошибка — 500 `INTERNAL_ERROR`. */
    41	export function sendError(res: http.ServerResponse, e: unknown, extra: Record<string, unknown> = {}): void {
    42	  const err = e instanceof PlatformError ? e : new PlatformError('INTERNAL_ERROR');
    43	  if (!(e instanceof PlatformError)) console.error(e);
    44	  sendJson(res, err.status, { error: { code: err.code, message: err.message }, ...extra });
